entries[19219] = { ["name"] = "Muster: Flimmerkernrobe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (300)\nBenutzen: Lehrt Euch die Herstellung einer Flimmerkernrobe.\nVerkaufspreis:\nFlimmerkernrobe\nWird beim Anlegen gebunden\nBrust Stoff\n222 Rüstung\n+35 Ausdauer\n+20 Intelligenz\n+15 Feuerwiderstand\nHaltbarkeit 165 / 165\nBenötigt Stufe 60\nVerkaufspreis:\nBenötigt Mondstoff (10), Feuerkern (2), Lavakern (3), Essenz des Feuers (6), Eisenweberseide (4)" }
entries[19220] = { ["name"] = "Muster: Flimmerkerngamaschen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (300)\nBenutzen: Lehrt Euch die Herstellung von Flimmerkerngamaschen.\nVerkaufspreis:\nFlimmerkerngamaschen\nWird beim Anlegen gebunden\nBeine Stoff\n205 Rüstung\n+21 Ausdauer\n+37 Intelligenz\n+16 Feuerwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nVerkaufspreis:\nBenötigt Mondstoff (8), Feuerkern (5), Lavakern (3), Essenz des Feuers (10), Eisenweberseide (4)" }
